function applyHunks(a, hunks) {
  if (!Array.isArray(hunks)) throw new Error('hunk 0 does not apply');
  const result = [];
  let cursor = 0;
  for (let index = 0; index < hunks.length; index++) {
    const fail = () => {
      throw new Error(`hunk ${index} does not apply`);
    };
    const hunk = hunks[index];
    if (!hunk || typeof hunk !== 'object') fail();
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (![oldStart, oldLines, newStart, newLines].every(
      value => Number.isSafeInteger(value) && value >= 0,
    ) || !Array.isArray(lines)) fail();
    if ((oldLines > 0 && oldStart === 0) ||
        (newLines > 0 && newStart === 0)) fail();
    const oldIndex = oldStart - (oldLines > 0 ? 1 : 0);
    const newIndex = newStart - (newLines > 0 ? 1 : 0);
    if (oldIndex < cursor || oldIndex > a.length ||
        oldLines > a.length - oldIndex ||
        newIndex !== result.length + oldIndex - cursor) fail();

    while (cursor < oldIndex) result.push(a[cursor++]);
    let produced = 0;
    for (const line of lines) {
      if (typeof line !== 'string' || line.length === 0) fail();
      const prefix = line[0];
      const original = line.slice(1);
      if (prefix === ' ' || prefix === '-') {
        if (cursor >= a.length || a[cursor] !== original) fail();
        cursor++;
      } else if (prefix !== '+') {
        fail();
      }
      if (prefix !== '-') {
        result.push(original);
        produced++;
      }
    }
    if (cursor !== oldIndex + oldLines || produced !== newLines) fail();
  }
  while (cursor < a.length) result.push(a[cursor++]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

